drop policy if exists "business_campaigns_member_write" on public.business_campaigns; create policy "business_campaigns_member_advanced_all" on public.business_campaigns for all to authenticated using (exists(select 1 from public.business_members bm join public.businesses b on b.id=bm.business_id where bm.business_id=business_campaigns.business_id and bm.user_id=auth.uid() and bm.role=any(array['owner'::business_member_role,'admin'::business_member_role,'manager'::business_member_role]) and b.business_tier <> 'standard'::business_tier)) with check (exists(select 1 from public.business_members bm join public.businesses b on b.id=bm.business_id where bm.business_id=business_campaigns.business_id and bm.user_id=auth.uid() and bm.role=any(array['owner'::business_member_role,'admin'::business_member_role,'manager'::business_member_role]) and b.business_tier <> 'standard'::business_tier));
